<section class="mt-8 max-w-3xl rounded-2xl border border-slate-200 bg-white p-6 dark:border-slate-800 dark:bg-slate-900"><h2 class="text-xl font-semibold">{{ $correction ? 'Correct source evidence' : 'Record source evidence' }}</h2><form method="POST" action="{{ route('context.store', $profile['id']) }}" class="mt-5 grid gap-5">@csrf<input type="hidden" name="expected_sequence" value="{{ old('expected_sequence', $sequence) }}"><x-select name="metric" label="Metric / context type" :required="true"><option value="">Select type</option>@foreach(App\OperationalMetric::cases() as $metric)<option value="{{ $metric->value }}" @selected(old('metric', $correction->metric->value ?? '') === $metric->value)>{{ $metric->label() }} · {{ $metric->unit() }}</option>@endforeach</x-select><div class="grid gap-5 sm:grid-cols-2"><x-select name="unit" label="Source unit" :required="true"><option value="">Select unit shown with the metric</option>@foreach(['hours', 'observations', 'percent', 'narrative'] as $unit)<option value="{{ $unit }}" @selected(old('unit', $correction->unit ?? '') === $unit)>{{ ucfirst($unit) }}</option>@endforeach</x-select><x-field name="value" label="Numeric value (leave empty for narrative)" type="number" min="0" max="999999.99" step="0.01" :value="$correction && $correction->value_hundredths !== null ? number_format($correction->value_hundredths / 100, 2, '.', '') : ''"/><x-field name="period_start" label="Source period start" type="date" :required="true" :value="$correction ? $correction->period_start->toDateString() : ''"/><x-field name="period_end" label="Source period end" type="date" :required="true" :value="$correction ? $correction->period_end->toDateString() : ''"/></div><x-textarea name="source" label="Source / reference" maxlength="1000" :required="true" :value="$correction->source ?? ''"/><x-textarea name="notes" label="Source notes / human interpretation" maxlength="8000" :value="$correction->notes ?? ''"/><p class="text-xs text-slate-500 dark:text-slate-400">Narrative context requires text. Percentage values must be 0–100; observations must be whole counts. HR confirms the period and metric policy before live use.</p>@if($correction)<input type="hidden" name="supersedes_id" value="{{ $correction->id }}"><x-textarea name="correction_reason" label="Correction reason" maxlength="1000" :required="true"/><p class="text-xs">Corrects entry #{{ $correction->id }}; its source evidence remains in history.</p>@endif<div><x-button :disabled="$correction && $correction->correction !== null">Record {{ $correction ? 'correction' : 'evidence' }}</x-button></div></form></section></x-layout>
